// src/components/Header.jsx
import React from 'react';
import { FaShoppingCart, FaUser } from 'react-icons/fa';
import { Link } from 'react-router-dom';

const Header = () => {
  const headerStyle = {
    backgroundColor: '#333',
    padding: '1rem 0',
    color: 'white',
  };

  const containerStyle = {
    maxWidth: '1200px',
    margin: '0 auto',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  };

  const logoStyle = {
    fontSize: '1.5rem',
    fontWeight: 'bold',
    textDecoration: 'none',
    color: 'white',
  };

  const navbarStyle = {
    display: 'flex',
    alignItems: 'center',
  };

  const searchBarStyle = {
    display: 'flex',
    alignItems: 'center',
    marginRight: '2rem',
  };

  const searchInputStyle = {
    padding: '0.5rem',
    border: 'none',
    borderRadius: '4px',
    marginRight: '0.5rem',
  };

  const searchButtonStyle = {
    backgroundColor: '#f8c146',
    border: 'none',
    padding: '0.5rem 1rem',
    color: 'white',
    cursor: 'pointer',
    borderRadius: '4px',
  };

  const navLinksStyle = {
    listStyle: 'none',
    display: 'flex',
    gap: '1rem',
  };

  const navItemStyle = {
    color: 'white',
    textDecoration: 'none',
    display: 'flex',
    alignItems: 'center',
  };

  const iconStyle = {
    marginRight: '0.5rem',
  };

  const navItemHover = (e) => {
    e.target.style.color = '#f8c146';
  };

  const navItemLeave = (e) => {
    e.target.style.color = 'white';
  };

  return (
    <header style={headerStyle}>
      <div style={containerStyle}>
        <Link to="/" style={logoStyle}>
          Proshop
        </Link>
        <nav style={navbarStyle}>
          <form style={searchBarStyle}>
            <input
              type="text"
              placeholder="Search Products..."
              style={searchInputStyle}
            />
            <button type="submit" style={searchButtonStyle}>
              Search
            </button>
          </form>
          <ul style={navLinksStyle}>
            <li>
              <Link
                to="/cart"
                style={navItemStyle}
                onMouseEnter={navItemHover}
                onMouseLeave={navItemLeave}
              >
                <FaShoppingCart style={iconStyle} />
                Cart
              </Link>
            </li>
            <li>
              <Link
                to="/login"
                style={navItemStyle}
                onMouseEnter={navItemHover}
                onMouseLeave={navItemLeave}
              >
                <FaUser style={iconStyle} />
                Sign In
              </Link>
            </li>
          </ul>
        </nav>
      </div>
    </header>
  );
};

export default Header;
